    export const getEstimateQualityRunUrl = (studyId: string,
    params?: EstimateQualityRunParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/studies/${studyId}/quality-runs/estimate?${stringifiedParams}` : `/api/studies/${studyId}/quality-runs/estimate`
}

